local rawset = rawset
local DialogueConvert = setmetatable({}, {
  __index = function (t, key)
    local Partition = DataMgr.QueryTable(key, "DialogueConvert", Data)
    if Partition then
      return Partition
    else
      return nil
    end
  end,
  __pairs = function(t)
    for _, partDef in ipairs(Data) do
      local Partition = DataMgr.GetPartitionData(partDef.MinKey, Data)
      if Partition then
        for k,v in pairs(Partition) do
            if rawget(t, k) == nil then
                rawset(t, k, v)
            end
          end
      end
    end
    return next, t, nil
  end,
})

return DialogueConvert
